{
  "command": "mkdir -p [scratch]/audit && cat > [scratch]/audit/apn_small.py <<'EOF'
# Exhaustive: APN permutations of F_2^m for m = 1, 2, 3 and whether their reduced representative has a critical point.
import itertools, sys
def field(m, mod):
    q = 1 << m
    def mul(a, b):
        r = 0
        while b:
            if b & 1: r ^= a
            b >>= 1; a <<= 1
            if a >> m: a ^= mod
        return r
    return q, mul
def powf(mul, a, e):
    r = 1
    for _ in range(e): r = mul(r, a)
    return r
def reduced_coeffs(q, mul, T):
    # Lagrange: a_j = sum_c F(c) c^(q-1-j) for j>=1 (0^0 = 1), a_0 = F(0)
    co = [0]*q
    co[0] = T[0]
    for j in range(1, q):
        s = 0
        for c in range(q):
            e = q-1-j
            s ^= mul(T[c], powf(mul, c, e) if not (c == 0 and e > 0) else 0) if not (c == 0 and e == 0) else T[c]
        co[j] = s
    return co
def crit(q, mul, co):
    roots = []
    for a in range(q):
        s = 0
        for k in range(1, q, 2):
            s ^= mul(co[k], powf(mul, a, k-1))
        if s == 0: roots.append(a)
    return roots
def du(q, T):
    d = 0
    for a in range(1, q):
        cnt = {}
        for x in range(q):
            b = T[x ^ a] ^ T[x]; cnt[b] = cnt.get(b, 0) + 1
        d = max(d, max(cnt.values()))
    return d
for m, mod in ((1, 0b11), (2, 0b111), (3, 0b1011)):
    q, mul = field(m, mod)
    napn = nocrit = 0
    ex = None
    for T in itertools.permutations(range(q)):
        if du(q, T) != 2: continue
        napn += 1
        co = reduced_coeffs(q, mul, list(T))
        # check reconstruct
        for x in range(q):
            v = 0
            for j in range(q): v ^= mul(co[j], powf(mul, x, j))
            assert v == T[x], (T, co)
        if not crit(q, mul, co):
            nocrit += 1
            if ex is None: ex = (T, co)
    print(f'm={m} q={q}: APN permutations {napn}, without critical point {nocrit}, example {ex}')
EOF
