# Random affine equivalents L1(F(L2(x)+c2))+c1 of APN power permutations: do their reduced representatives have critical points?
import random, sys
def setup(m, mod):
    q = 1 << m
    def mul(a, b):
        r = 0
        while b:
            if b & 1: r ^= a
            b >>= 1; a <<= 1
            if a >> m: a ^= mod
        return r
    # primitive element tables
    for g in range(2, q):
        exp = []; x = 1
        for i in range(q-1):
            exp.append(x); x = mul(x, g)
        if len(set(exp)) == q-1: break
    log = [0]*q
    for i, v in enumerate(exp): log[v] = i
    return q, mul, exp, log
def rand_linear(m, rng):
    while True:
        cols = [rng.randrange(1 << m) for _ in range(m)]
        # rank check
        rows = cols[:]; r = 0
        basis = []
        for v in cols:
            for b in basis:
                v = min(v, v ^ b)
            if v: basis.append(v)
        if len(basis) == m:
            def L(x, cols=cols):
                s = 0
                for i in range(m):
                    if (x >> i) & 1: s ^= cols[i]
                return s
            return L
def main(m, mod, exps, trials, seed):
    q, mul, exp, log = setup(m, mod)
    rng = random.Random(seed)
    def pw(a, e):
        if a == 0: return 0 if e else 1
        return exp[(log[a]*e) % (q-1)]
    for d in exps:
        base = [pw(x, d) for x in range(q)]
        assert len(set(base)) == q
        nocrit = 0
        for t in range(trials):
            L1, L2 = rand_linear(m, rng), rand_linear(m, rng)
            c1, c2 = rng.randrange(q), rng.randrange(q)
            T = [L1(base[L2(x) ^ c2]) ^ c1 for x in range(q)]
            # reduced coeffs odd k
            co = {}
            for k in range(1, q, 2):
                s = 0
                for c in range(q):
                    if k == q-1:
                        s ^= T[c]
                    elif c:
                        v = T[c]
                        if v: s ^= exp[(log[v] - log[c]*k) % (q-1)]
                co[k] = s
            has = False
            for a in range(q):
                s = 0
                for k, c in co.items():
                    if c: s ^= mul(c, pw(a, k-1))
                if s == 0: has = True; break
            if not has:
                nocrit += 1
                if nocrit == 1: print(' example', d, T)
        print(f'm={m} d={d}: {trials} affine equivalents, without critical point: {nocrit}', flush=True)
main(5, 0b100101, [3, 5, 7, 11, 13, 15, 30], 300, 1)
