{
  "command": "cat > [scratch]/audit/gr_lift.py <<'EOF'
# Independent check of Ronjom-Sandrib Conjecture 2 at a given APN permutation table of F_(2^m):
# compute the reduced representative by Lagrange interpolation, lift its coefficients to GR(4, m) with 0/1 digits,
# and test whether the lift permutes GR(4, m). No derivative is computed here.
import json, sys, itertools
def main(m, mod, T):
    q = 1 << m
    def fmul(a, b):
        r = 0
        while b:
            if b & 1: r ^= a
            b >>= 1; a <<= 1
            if a >> m: a ^= mod
        return r
    def fpow(a, e):
        r = 1
        for _ in range(e): r = fmul(r, a)
        return r
    # APN and bijective on F_q
    assert sorted(T) == list(range(q))
    du = max(max([sum(1 for x in range(q) if T[x ^ a] ^ T[x] == b) for b in range(q)]) for a in range(1, q))
    # reduced representative: f(x) = sum_c F(c) (1 + (x + c)^(q-1)) expanded by brute force polynomial arithmetic
    coeffs = [0] * q
    for c in range(q):
        # (x + c)^(q-1) = sum_j x^j c^(q-1-j) (binomials are all odd)
        coeffs[0] ^= T[c]
        for j in range(q):
            coeffs[j] ^= fmul(T[c], fpow(c, q - 1 - j))
    for x in range(q):
        v = 0
        for j in range(q): v ^= fmul(coeffs[j], fpow(x, j))
        assert v == T[x]
    degree = max(j for j in range(q) if coeffs[j])
    # GR(4, m) = Z4[y]/(h), h = lift of the modulus with 0/1 coefficients (monic, basic irreducible)
    h = [(mod >> i) & 1 for i in range(m + 1)]
    def rmul(a, b):
        prod = [0] * (2 * m - 1)
        for i, ai in enumerate(a):
            if ai:
                for j, bj in enumerate(b):
                    prod[i + j] = (prod[i + j] + ai * bj) % 4
        for d in range(2 * m - 2, m - 1, -1):
            c = prod[d]
            if c:
                for i in range(m + 1):
                    prod[d - m + i] = (prod[d - m + i] - c * h[i]) % 4
        return tuple(prod[:m])
    def radd(a, b): return tuple((x + y) % 4 for x, y in zip(a, b))
    lift = [tuple((c >> i) & 1 for i in range(m)) for c in coeffs]
    zero = tuple([0] * m)
    images = set()
    for x in itertools.product(range(4), repeat=m):
        acc = zero
        for k in range(q - 1, -1, -1):  # Horner
            acc = radd(rmul(acc, x), lift[k])
        images.add(acc)
    print(json.dumps({'m': m, 'differential_uniformity': du, 'reduced_degree': degree,
                      'GR(4,m) size': 4 ** m, 'distinct images of the lift': len(images),
                      'lift permutes GR(4,m)': len(images) == 4 ** m}))
cases = {
    'm1-identity': (1, 0b11, [0, 1]),
    'm5-affine-x3': (5, 0b100101, [12, 29, 13, 9, 31, 6, 24, 20, 3, 17, 25, 30, 15, 21, 19, 28, 1, 11, 23, 8, 2, 0, 18, 5, 7, 14, 10, 22, 27, 26, 16, 4]),
    'm5-affine-inverse': (5, 0b100101, [27, 24, 21, 3, 14, 30, 4, 15, 12, 5, 1, 7, 8, 13, 26, 29, 22, 23, 11, 19, 9, 28, 10, 20, 25, 6, 18, 16, 0, 17, 31, 2]),
    'm5-x3-monomial-control': (5, 0b100101, None),
}
for name, (m, mod, T) in cases.items():
    if T is None:
        q = 1 << m
        def fm(a, b):
            r = 0
            while b:
                if b & 1: r ^= a
                b >>= 1; a <<= 1
                if a >> m: a ^= mod
            return r
        T = [fm(fm(x, x), x) for x in range(q)]
    print(name, end=' ')
    main(m, mod, T)
EOF
