{
  "command": "cat > [scratch]/audit/apn_simple.py <<'EOF'
# Find a closed-form counterexample at m = 5: F(x) = L1((L2(x))^3) with L1(y) = y + c*y^(2^j) and L2 = identity,
# or F(x) = (x + b*x^(2^i))^3, both GF(2)-linear compositions with the APN permutation x^3.
m, mod = 5, 0b100101
q = 1 << m
def mul(a, b):
    r = 0
    while b:
        if b & 1: r ^= a
        b >>= 1; a <<= 1
        if a >> m: a ^= mod
    return r
def pw(a, e):
    r = 1
    for _ in range(e): r = mul(r, a)
    return r
def du(T):
    return max(max([sum(1 for x in range(q) if T[x ^ a] ^ T[x] == b) for b in range(q)]) for a in range(1, q))
def crit(T):
    co = {}
    for k in range(1, q, 2):
        s = 0
        for c in range(q):
            s ^= mul(T[c], pw(c, q - 1 - k))
        co[k] = s
    roots = [a for a in range(q) if not eval_(co, a)]
    return co, roots
def eval_(co, a):
    s = 0
    for k, c in co.items(): s ^= mul(c, pw(a, k - 1))
    return s
found = []
for form in ('outer', 'inner'):
    for j in range(1, m):
        for c in range(1, q):
            if form == 'outer':
                T = [pw(x, 3) ^ mul(c, pw(pw(x, 3), 1 << j)) for x in range(q)]
                desc = f'x^3 + {c}*x^(3*2^{j})'
            else:
                T = [pw(x ^ mul(c, pw(x, 1 << j)), 3) for x in range(q)]
                desc = f'(x + {c}*x^(2^{j}))^3'
            if len(set(T)) != q: continue
            if du(T) != 2: continue
            co, roots = crit(T)
            if not roots:
                found.append((form, desc, T, {k: v for k, v in co.items() if v}))
    print(form, 'count', sum(1 for f in found if f[0] == form))
for f in found[:4]:
    print(f[1], 'table', f[2], 'odd coeffs', f[3])
# the simplest: c = 1 (the field element 1)
print('with c = 1:', [f[1] for f in found if '+ 1*' in f[1]])
EOF
