# Closed-form search at m = 5: F(x) = x^3 + d*Tr(x^3) (outer) and F(x) = (x + d*Tr(x))^3 (inner), Tr(d) = 0.
m, mod = 5, 0b100101
q = 1 << m
def mul(a, b):
    r = 0
    while b:
        if b & 1: r ^= a
        b >>= 1; a <<= 1
        if a >> m: a ^= mod
    return r
def pw(a, e):
    r = 1
    for _ in range(e): r = mul(r, a)
    return r
def tr(x):
    s, y = 0, x
    for _ in range(m): s ^= y; y = mul(y, y)
    return s
def du(T):
    return max(max([sum(1 for x in range(q) if T[x ^ a] ^ T[x] == b) for b in range(q)]) for a in range(1, q))
def odd_coeffs(T):
    return {k: s for k in range(1, q, 2) if (s := _c(T, k))}
def _c(T, k):
    s = 0
    for c in range(q): s ^= mul(T[c], pw(c, q - 1 - k))
    return s
def roots(co):
    out = []
    for a in range(q):
        s = 0
        for k, c in co.items(): s ^= mul(c, pw(a, k - 1))
        if not s: out.append(a)
    return out
for d in range(1, q):
    if tr(d): continue
    for form, T in (('x^3 + d*Tr(x^3)', [pw(x, 3) ^ mul(d, tr(pw(x, 3))) for x in range(q)]),
                    ('(x + d*Tr(x))^3', [pw(x ^ mul(d, tr(x)), 3) for x in range(q)])):
        assert len(set(T)) == q and du(T) == 2
