def mul(a: int, b: int, m: int, mod: int) -> int:
    r = 0
    while b:
        if b & 1:
            r ^= a
        b >>= 1
        a <<= 1
        if a >> m:
            a ^= mod
    return r


def power(a: int, e: int, m: int, mod: int) -> int:
    r = 1
    while e:
        if e & 1:
            r = mul(r, a, m, mod)
        a = mul(a, a, m, mod)
        e >>= 1
    return r


def inverse(a: int, m: int, mod: int) -> int:
    return power(a, (1 << m) - 2, m, mod)

