#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

/* APN critical-point search. Mirrors inputs/checks/apn-critical-point.py exactly:
   reduced coeffs a_k (odd k), f' = XOR a_k x^(k-1), 0^0=1, roots over all F_q. */

static int M, Q, QM1, MOD;
static uint16_t E[2 * 2048];
static int L[2048];

static inline int bits(int a) { return a ? 32 - __builtin_clz(a) : 0; }

static int pmod(int a, int b) {
    int db = bits(b) - 1;
    while (a && (bits(a) - 1) >= db) a ^= b << (bits(a) - 1 - db);
    return a;
}
}
/* number of critical points of the reduced representative (checker-exact); roots opt. out */
static int critical_roots(const uint16_t *T, uint16_t *roots) {
    static uint16_t coef[2048]; static int ks[2048];
    int nt = 0;
    for (int k = 1; k < QM1; k += 2) {
        uint16_t s = 0;
        for (int c = 1; c < Q; c++) {
            uint16_t v = T[c];
            if (v) s ^= E[(L[v] + QM1 - ((int)(((uint64_t)L[c] * k) % QM1))) % QM1];
        }
        if (s) { coef[nt] = s; ks[nt] = k; nt++; }
    }
    uint16_t tot = 0;
    for (int c = 0; c < Q; c++) tot ^= T[c];
    if (tot) { coef[nt] = tot; ks[nt] = QM1; nt++; }
