\section{The reduction: From Galois rings to critical points}
\label{sec:reduction}

Theorem~\ref{thm:main-reduction} follows immediately from the standard criterion in Theorem~\ref{thm:gr-permutation-criterion}. For completeness, this section gives a direct proof in the special case needed here. The argument passes to $\GR(4,m)$ and uses the exact first-order Taylor expansion in its square-zero ideal $(2)$.

%\subsection{Reduction from arbitrary $k$ to $k=2$}

We begin with two standard facts on Galois rings that will be used repeatedly.
\end{lem}

\begin{proof}
If $a\in I$, then $a^2\in I^2=0$ (Lemma~\ref{lem:gr4-struct}(i)), so $a$ is nilpotent and hence not a unit.
Conversely, suppose $\bar a\neq 0$ in the field $R/I$. Choose $\bar b\in R/I$ with $\bar a\,\bar b=1$ and pick any lift $b\in R$ of $\bar b$.
Then $ab\equiv 1\pmod I$, so $ab=1+2c$ for some $c\in R$.
Since $(2c)^2=4c^2=0$, we have $(1+2c)(1-2c)=1$ in $R$.
Thus $a\cdot \bigl(b(1-2c)\bigr)=1$, so $a$ is a unit.
\end{proof}

\begin{prop}%[Nowhere-critical permutations lift to $\GR(4,m)$]
\label{prop:derivative-sufficient}
Let $f\in \F_{2^m}[x]$ be a permutation polynomial such that $f'(a)\neq 0$ for all $a\in \F_{2^m}$.
Let $F\in \GR(4,m)[x]$ be any polynomial lift of $f$ (i.e.\ $F\bmod 2=f$ coefficient-wise).
Then $F$ induces a permutation of $\GR(4,m)$.
\end{prop}

\begin{proof}
Let $R=\GR(4,m)$ and $I=(2)$. By hypothesis, the reduction $\bar F:R/I\to R/I$ coincides with $f$, hence is bijective.
Fix $t\in T$. By Lemma~\ref{lem:taylor-expansion},
\[
\Delta_t(y)=F(t+y)-F(t)=yF'(t)\qquad (y\in I).
