{
  "file_path": "[scratch]/audit/le.c",
  "content": "// Complete guess-and-determine linear-equivalence search (Biryukov et al. 2003 style).
// Finds invertible GF(2)-linear A, B with S(x) = B(P(A(x))) for all x, where S, P are
// permutations of F_2^m fixing 0. Prints the first solution, or "NONE" after exhausting
// every branch. Input on stdin: m, then S[0..q-1], then P[0..q-1].
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXQ 1024
static int m, q;
static int S[MAXQ], Sinv[MAXQ], P[MAXQ], Pinv[MAXQ];
static long long nodes = 0;

typedef struct {
  short fwd[MAXQ], inv[MAXQ];
  short span[MAXQ];
  int n;  // number of points in domain span
} PL;

typedef struct {
  PL A, B;
  short qa[MAXQ], qb[MAXQ];
  int na, nb;
} St;

static void pl_init(PL *L) {
  for (int i = 0; i < q; i++) L->fwd[i] = L->inv[i] = -1;
  L->fwd[0] = 0; L->inv[0] = 0; L->span[0] = 0; L->n = 1;
}

// add pair x -> y; returns 0 on contradiction; appends newly-known domain points to out
static int pl_add(PL *L, int x, int y, short *out, int *nout) {
  if (L->fwd[x] >= 0) return L->fwd[x] == y;
  if (L->inv[y] >= 0) return 0;
  int n = L->n;
  for (int i = 0; i < n; i++) {
    int v = L->span[i];
    int nx = v ^ x, ny = L->fwd[v] ^ y;
    L->fwd[nx] = ny; L->inv[ny] = nx;
    L->span[n + i] = nx;
    out[(*nout)++] = nx;
  }
  L->n = 2 * n;
  return 1;
}

static int propagate(St *s) {
  while (s->na || s->nb) {
    while (s->na) {
      int x = s->qa[--s->na];
      int w = s->A.fwd[x];
      if (!pl_add(&s->B, P[w], S[x], s->qb, &s->nb)) return 0;
    }
    while (s->nb) {
      int y = s->qb[--s->nb];
      int z = s->B.fwd[y];
      if (!pl_add(&s->A, Sinv[z], Pinv[y], s->qa, &s->na)) return 0;
    }
  }
  return 1;
}

static int found = 0;
static St sol;

static void search(St *s) {
  nodes++;
  if (!propagate(s)) return;
  if (s->A.n == q) {
    for (int x = 0; x < q; x++)
      if (s->B.fwd[P[s->A.fwd[x]]] != S[x]) { fprintf(stderr, "BUG verify\n"); exit(9); }
    sol = *s; found = 1; return;
  }
  int x = 1;
  while (s->A.fwd[x] >= 0) x++;
  for (int w = 1; w < q && !found; w++) {
    if (s->A.inv[w] >= 0) continue;
    St *t = malloc(sizeof(St));
    *t = *s;
    t->na = t->nb = 0;
    if (pl_add(&t->A, x, w, t->qa, &t->na)) search(t);
    free(t);
  }
}

int main(void) {
  if (scanf("%d", &m) != 1) return 1;
  q = 1 << m;
  for (int i = 0; i < q; i++) if (scanf("%d", &S[i]) != 1) return 1;
  for (int i = 0; i < q; i++) if (scanf("%d", &P[i]) != 1) return 1;
  for (int i = 0; i < q; i++) { Sinv[S[i]] = i; Pinv[P[i]] = i; }
  if (S[0] || P[0]) { fprintf(stderr, "S(0), P(0) must be 0\n"); return 1; }
  St *s = malloc(sizeof(St));
  pl_init(&s->A); pl_init(&s->B); s->na = s->nb = 0;
  search(s);
  if (!found) { printf("NONE nodes=%lld\n", nodes); return 0; }
  printf("FOUND nodes=%lld\nA", nodes);
  for (int i = 0; i < m; i++) printf(" %d", sol.A.fwd[1 << i]);
  printf("\nB");
  for (int i = 0; i < m; i++) printf(" %d", sol.B.fwd[1 << i]);
  printf("\n");
  return 0;
}
