{
  "command": "cat > [scratch]/gr_lift.py <<'EOF'
#!/usr/bin/env python3
"""End-to-end check of Conjecture 1 (lifting) for a table artifact: lift the reduced
representative coefficientwise to GR(4,m)=Z4[xi]/(h), h = monic Z4 lift of the modulus,
evaluate on all 4^m elements, report bijectivity. Also Walsh spectrum over F_2^m."""
import json, sys
from scope_probe import make, reduced_coeffs

def gr(m, mod):
    h = [(mod >> i) & 1 for i in range(m + 1)]  # monic, coefficients 0/1 in Z4
    def mul(a, b):
        r = [0] * (2 * m - 1)
        for i, x in enumerate(a):
            if x:
                for j, y in enumerate(b):
                    if y: r[i + j] = (r[i + j] + x * y) % 4
        for d in range(2 * m - 2, m - 1, -1):
            c = r[d]
            if c:
                for i in range(m + 1):
                    r[d - m + i] = (r[d - m + i] - c * h[i]) % 4
        return tuple(r[:m])
    def add(a, b):
        return tuple((x + y) % 4 for x, y in zip(a, b))
    elems = []
    for n in range(4 ** m):
        v = []
        for _ in range(m):
            v.append(n % 4); n //= 4
        elems.append(tuple(v))
    return mul, add, elems

def lift_perm(T, m, mod):
    q, M, P = make(m, mod)
    a = reduced_coeffs(T, q, M, P)
    mul, add, elems = gr(m, mod)
    A = [tuple((c >> i) & 1 for i in range(m)) for c in a]  # coefficientwise lift
    deg = max(k for k in range(q) if a[k])
    zero = tuple([0] * m)
    img = set()
    for x in elems:
        s = zero
        for k in range(deg, -1, -1):  # Horner
            s = add(mul(s, x), A[k])
        img.add(s)
    return len(img), len(elems), deg

def walsh(T, m):
    q = 1 << m
    vals = set()
    for u in range(q):
        for v in range(1, q):
            s = 0
            for x in range(q):
                s += -1 if (bin(v & T[x]).count('1') + bin(u & x).count('1')) & 1 else 1
            vals.add(abs(s))
    return sorted(vals)

if __name__ == '__main__':
    path, m, mod = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
    if path == 'x3':
        q, M, P = make(m, mod)
        T = [M[M[x][x]][x] for x in range(q)]
        name = 'x^3 control'
    else:
        T = json.load(open(path))['artifact']['table']; name = path.split('/')[-1]
    n, N, deg = lift_perm(T, m, mod)
    out = {'artifact': name, 'GR(4,%d) lift image size' % m: n, 'ring size': N, 'lift is permutation': n == N, 'reduced degree': deg}
    if m <= 7 and len(sys.argv) > 4:
        out['|Walsh| values'] = walsh(T, m)
    print(json.dumps(out))
