  "content": "#!/usr/bin/env python3
"""How often is a uniformly random GF(2)-affine equivalent A1 o x^d o A2 of an APN power permutation
nowhere critical? Also exhaust all 40320 permutations of F_8 (m = 3)."""
import itertools, json, random, sys
import numpy as np
from audit import Field, fast_crit_count, apn_power_perm_classes, bmul

MODS = {3: 11, 5: 37, 7: 131, 9: 529}
N = {3: 3000, 5: 3000, 7: 600, 9: 150}


def rand_invertible(m, rng):
    while True:
        M = [rng.randrange(1 << m) for _ in range(m)]
        rows, r = list(M), 0
        for bit in range(m):
            p = next((i for i in range(r, m) if rows[i] >> bit & 1), None)
            if p is None:
                break
            rows[r], rows[p] = rows[p], rows[r]
            for i in range(m):
                if i != r and rows[i] >> bit & 1:
                    rows[i] ^= rows[r]
            r += 1
        if r == m:
            return M


def lin_table(M, m):
    q = 1 << m
    t = np.zeros(q, dtype=np.int64)
    for x in range(1, q):
        low = x & -x
        t[x] = t[x ^ low] ^ M[low.bit_length() - 1]
    return t


def main():
    rng = random.Random(20260927)
    out = {}
    for m in (3, 5, 7, 9):
        K = Field(m, MODS[m])
        q = K.q
        ds, classes = apn_power_perm_classes(K)
        row = {}
        for cl in classes:
            d = cl[0]
            G = K.powtable(d)
            hits = 0
            for _ in range(N[m]):
                L1, L2 = lin_table(rand_invertible(m, rng), m), lin_table(rand_invertible(m, rng), m)
                c1, c2 = rng.randrange(q), rng.randrange(q)
                T = L1[G[L2 ^ c2]] ^ c1  # A1(G(A2(x))): A2 x = L2 x + c2
                T = L1[G[L2[np.arange(q)] ^ c2]] ^ c1
                if fast_crit_count(K, T) == 0:
                    hits += 1
            row[f'x^{d}'] = f'{hits}/{N[m]}'
        out[m] = row
        print(json.dumps({m: row}), flush=True)
    # m = 3 exhaustive over every permutation
