# Search f(x) = g(x^2) + L(x) with g = x^3 (Gold), L linearized with nonzero x-coefficient.
# By Lemmas 6.6/6.7 of arXiv:2608.30808, f' == L's x-coefficient (nonzero) and f is APN iff g is APN.
import sys,random,itertools
sys.path.insert(0,'.')
from gf import GF
random.seed(1)
for m in [3,5,7]:
    K=GF(m);q=K.q
    sq=[K.pw(x,6) for x in range(q)]
    fr=[[K.pw(x,1<<i) for x in range(q)] for i in range(m)]
    found=[];tries=0
    if m<=3:
        space=itertools.product(range(1,q),*[range(q)]*(m-1))
    else:
        space=(tuple([random.randrange(1,q)]+[random.randrange(q) for _ in range(m-1)]) for _ in range(200000))
    for co in space:
        tries+=1
        F=[sq[x] for x in range(q)]
        for i,c in enumerate(co):
            if c:
                for x in range(q): F[x]^=K.mul(c,fr[i][x])
        if len(set(F))==q:
            found.append(co)
            if len(found)>=3: break
    print('m',m,'tries',tries,'permutations found',len(found))
    for co in found[:3]:
        F=[sq[x] for x in range(q)]
        for i,c in enumerate(co):
            for x in range(q): F[x]^=K.mul(c,fr[i][x])
        cr,red=K.crit(F)
        terms={k:red[k] for k in range(q) if red[k]}
        print('   L coeffs (x,x^2,x^4,..)',co,'du',K.du(F),'crit',len(cr),'reduced terms',terms)
EOF
