\label{cor:nonapn-even}
Let $e\ge5$ be odd and neither a Gold nor a Kasami--Welch number, and set $d=2e$. Then no polynomial of the form
\[
f(x)=ax+g(x^2)+c\in\F_{2^m}[x],\qquad a\in\F_{2^m}^\times,\ \deg g=e,
\]
is APN for any $m\ge\APNmzero{e}$, with $\APNmzero{\cdot}$ the polynomial-degree threshold of Corollary~\textup{\ref{cor:nonapn-large-generic}}.
\end{corollary}

\begin{proof}
Corollary~\ref{cor:nonapn-large-generic} shows that $g$ is not APN for $m\ge\APNmzero{e}$. Lemma~\ref{lem:differential-transfer} gives equality of the differential uniformities of $f$ and $g$, so $f$ is not APN in the same range.
\end{proof}

We are now able to handle the degree-3 case, by proving one more lemma.

\begin{lemma}
%[Critical points for cubic permutation polynomials]
\label{lem:degree-3}
Let $q=2^m$ and let $f\in\F_q[x]$ be any permutation polynomial of degree $3$. Then $f$ has a critical point in $\F_q$.
\end{lemma}

\begin{proof}
Write $f(x)=ax^3+bx^2+cx+d$ with $a\neq 0$. In characteristic $2$, the formal derivative is $f'(x)=ax^2+c$ (the $bx^2$ term contributes zero since $\binom{2}{1}=2\equiv 0$). If $c=0$ then $f'(0)=0$. If $c\neq 0$, the equation $f'(x)=0$ reduces to $x^2=c/a$, which has a solution in $\F_q$ because the Frobenius $x\mapsto x^2$ is a bijection of $\F_q$. In both cases $f$ has a critical point.
\end{proof}

\begin{proof}[Proof of Theorem~\textup{\ref{thm:high-degree}}]
This is Corollary~\ref{cor:nonapn-large-generic}, with the degree of the Janwa--Wilson--Rodier surface equal to $d-3$ because $d$ is odd.
\end{proof}

\begin{proof}[Proof of Theorem~\textup{\ref{thm:high-degree-even}}]
Write $f(x)=ax+g(x^2)+c$ with $a\neq0$ and $\deg g=e$; then $f'\equiv a\neq0$ by Lemma~\ref{lem:constant-derivative-normal-form}. Lemma~\ref{lem:differential-transfer} shows
