  "content": "#!/usr/bin/env python3
"""Referee recheck of the three apn-critical-point claims, written apart from the frozen checker
and the five audit lenses. Bitwise field arithmetic only; every derived polynomial is re-evaluated
at every field element, so its coefficients certify themselves.

For each claim: modulus irreducibility (Rabin), bijectivity, full differential uniformity,
reduced representative, its true degree and top odd exponent, critical points of f'.
Then: the equivalence certificates of the equivalence lens, re-evaluated pointwise here, and a
hand-checkable counterexample F(x) = (x + x^8 + x^16)^3 on GF(32).
"""
import json
import sys

RUN = '/mnt/traces/discovery-runs/subscription-apn-glm-lab-20260927c/workspace/claims'


def mul(a, b, m, mod):
    r = 0
    while b:
        if b & 1:
            r ^= a
        b >>= 1
        a <<= 1
        if a >> m:
            a ^= mod
    return r


def power(a, e, m, mod):
    r = 1
    while e:
        if e & 1:
            r = mul(r, a, m, mod)
        a = mul(a, a, m, mod)
        e >>= 1
    return r


def pmod(a, b):
    db = b.bit_length() - 1
    while a and a.bit_length() - 1 >= db:
        a ^= b << (a.bit_length() - 1 - db)
    return a


def pgcd(a, b):
    while b:
        a, b = b, pmod(a, b)
    return a


def pmulmod(a, b, mod):
    r = 0
    while b:
